{
  "findings": [
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 bucket does not have cross-region replication enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not configured for cross-region replication, which could lead to data loss in case of a region-specific disaster."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not have object lock enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have object lock enabled, which could lead to accidental or malicious deletion of objects."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 bucket does not have logging enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have logging enabled, making it difficult to track and monitor access and changes to the bucket."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket does not have versioning enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have versioning enabled, which means that objects cannot be recovered in case of accidental deletion or overwrite."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"changeme_aws_s3_bucket_backend_simple\" {
  force_destroy = true
  bucket        = \"changeme-${random_id.changeme_backends_s3_bucket_name.hex}\"

  versioning {
    enabled = true
  }

  logging {
    target_bucket = \"${aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id}-logs\"
    target_prefix = \"/logs/\"
  }

  # Object lock configuration requires a separate resource
  # server-side encryption is not added as it requires more context (e.g., kms key)
}

resource \"aws_s3_bucket\" \"changeme_aws_s3_bucket_backend_simple_logs\" {
  bucket = \"${aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id}-logs\"
  acl    = \"log-delivery-write\"

  # To avoid a circular dependency, this bucket should be created separately
  # and its ARN passed as a variable or data source.
}

resource \"aws_s3_bucket_versioning\" \"changeme_aws_s3_bucket_backend_simple_versioning\" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  versioning_configuration {
    status = \"Enabled\"
  }
}

resource \"aws_s3_bucket_logging\" \"changeme_aws_s3_bucket_backend_simple_logging\" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  target_bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple_logs.id
  target_prefix = \"/logs/\"
}",
  "fix_summary": "Enabled versioning on the S3 bucket and added logging configuration. Created a new S3 bucket for storing logs. Note that object lock and cross-region replication require additional configuration and resources."
}
